package de.schaepi.puls180;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.bluetooth.BluetoothAdapter;
public class MeasurementService extends Service {
private MainBluetoothReceiver receiver;
private final Handler licenseHandler=new Handler(Looper.getMainLooper());
private final Runnable expiry=new Runnable(){public void run(){if(!License.allowed(MeasurementService.this)){if(receiver!=null)receiver.stop();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();return;}licenseHandler.postDelayed(this,Math.max(1,Math.min(30000,License.remaining(MeasurementService.this))));}};
public static boolean ensure(Context c){if(!License.allowed(c))return false;if(!c.getSharedPreferences("bluetooth",0).getBoolean("background",true)||(Build.VERSION.SDK_INT>=31&&c.checkSelfPermission("android.permission.BLUETOOTH_CONNECT")!=PackageManager.PERMISSION_GRANTED)||!BluetoothAdapter.checkBluetoothAddress(c.getSharedPreferences("bluetooth",0).getString("device","")))return false;try{c.startForegroundService(new Intent(c,MeasurementService.class));return true;}catch(RuntimeException e){c.getSharedPreferences("bluetooth",0).edit().putString("backgroundStatus","Hintergrundempfang konnte nicht gestartet werden. App öffnen und Freigaben prüfen.").apply();return false;}}
public IBinder onBind(Intent i){return null;}
public int onStartCommand(Intent i,int flags,int id){if(!License.allowed(this)){stopSelf();return START_NOT_STICKY;}licenseHandler.removeCallbacks(expiry);licenseHandler.post(expiry);if(i!=null&&"stop".equals(i.getAction())){getSharedPreferences("bluetooth",0).edit().putBoolean("background",false).apply();stopSelf();return START_NOT_STICKY;}if(!getSharedPreferences("bluetooth",0).getBoolean("background",true)||(Build.VERSION.SDK_INT>=31&&checkSelfPermission("android.permission.BLUETOOTH_CONNECT")!=PackageManager.PERMISSION_GRANTED)){stopSelf();return START_NOT_STICKY;}NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("measurement","Bluetooth-Messungsempfang",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,MeasurementService.class).setAction("stop"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notice=new Notification.Builder(this,"measurement").setSmallIcon(android.R.drawable.stat_sys_data_bluetooth).setContentTitle("Puls 180 – Messungsempfang").setContentText("Wartet auf das gespeicherte Bluetooth-Gerät").setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,"Beenden",stop).build()).build();try{startForeground(44,notice,ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE);}catch(RuntimeException e){stopSelf();return START_NOT_STICKY;}if(receiver==null){receiver=new MainBluetoothReceiver(this,()->sendBroadcast(new Intent(getPackageName()+".MEASUREMENT").setPackage(getPackageName())));receiver.start();}return START_STICKY;}
public void onDestroy(){licenseHandler.removeCallbacks(expiry);if(receiver!=null)receiver.stop();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}



